INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$اللَّهُمَّ إِنِّي عَبْدُكَ، ابْنُ عَبْدِكَ، ابْنُ أَمَتِكَ، نَاصِيَتِي بِيَدِكَ، مَاضٍ فِيَّ حُكْمُكَ، عَدْلٌ فِيَّ قَضَاؤُكَ، أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ، سَمَّيْتَ بِهِ نَفْسَكَ، أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ، أَوْ عَلَّمْتَهُ أَحَداً مِنْ خَلْقِكَ، أَوِ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الْغَيْبِ عِنْدَكَ، أَنْ تَجْعَلَ الْقُرْآنَ رَبِيعَ قَلْبِي، وَنُورَ صَدْرِي، وَجَلاَءَ حُزْنِي، وَذَهَابَ هَمِّي$q$, $q$Allahoumma inni ʿabdouka, oubnou ʿabdika, oubnou amatika, nasiyati biyadika, madin fiyya houkmouka, ʿadloun fiyya qada’ouka, as’alouka bikoulli-smin houwa laka, sammayta bihi nafsaka, aw anzaltahou fi kitabika, aw ʿallamtahou ahadan min khalqika, awi-sta’tharta bihi fi ʿilmi l-ghaybi ʿindaka, an tadjʿala l-qour’ana rabiʿa qalbi, wanoura sadri, wadjala’a houzni, wadhahaba hammi$q$, $q$Ô Allah, je suis Ton serviteur, fils de Ton serviteur, fils de Ta servante ; mon toupet est dans Ta main, Ton jugement s’exécute sur moi, Ton décret à mon égard est juste. Je Te demande par chacun de Tes noms, ceux dont Tu T’es nommé Toi-même, que Tu as révélés dans Ton Livre, enseignés à l’une de Tes créatures ou gardés pour Toi dans la science de l’invisible : fais du Coran le printemps de mon cœur, la lumière de ma poitrine, ce qui dissipe ma tristesse et emporte mon souci.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Tristesse et souci », invocation n° 1. Ahmad 1/391 ; jugé sahih par al-Albani.$q$, 1, 400, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$اللَّهُمَّ إِنِّي عَبْدُكَ، ابْنُ عَبْدِكَ، ابْنُ أَمَتِكَ، نَاصِيَتِي بِيَدِكَ، مَاضٍ فِيَّ حُكْمُكَ، عَدْلٌ فِيَّ قَضَاؤُكَ، أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ، سَمَّيْتَ بِهِ نَفْسَكَ، أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ، أَوْ عَلَّمْتَهُ أَحَداً مِنْ خَلْقِكَ، أَوِ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الْغَيْبِ عِنْدَكَ، أَنْ تَجْعَلَ الْقُرْآنَ رَبِيعَ قَلْبِي، وَنُورَ صَدْرِي، وَجَلاَءَ حُزْنِي، وَذَهَابَ هَمِّي$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ$q$, $q$Allahoumma inni aʿoudhou bika mina l-hammi wal-hazani, wal-ʿadjzi wal-kasali, wal-boukhli wal-djoubni, wadalaʿi d-dayni waghalabati r-ridjal$q$, $q$Ô Allah, je cherche refuge auprès de Toi contre le souci et la tristesse, l’impuissance et la paresse, l’avarice et la lâcheté, le poids de la dette et la domination des hommes. (la même formule se dit aussi pour être aidé à rembourser une dette)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Tristesse et souci », invocation n° 2. Al-Bukhari 7/158 : le Messager d’Allah multipliait cette invocation. Le même texte figure dans le chapitre « rembourser une dette » (at-Tirmidhi 5/560, voir Sahih at-Tirmidhi 3/180 ; al-Bukhari 7/158).$q$, 1, 401, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$لاَ إِلَهَ إِلاَّ اللَّهُ الْعَظِيمُ الْحَلِيمُ، لاَ إِلَهَ إِلاَّ اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ، لاَ إِلَهَ إِلاَّ اللَّهُ رَبُّ السَّمَوَاتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيمِ$q$, $q$La ilaha illa llahou l-ʿadhimou l-halimou, la ilaha illa llahou rabbou l-ʿarchi l-ʿadhimi, la ilaha illa llahou rabbou s-samawati warabbou l-ardi warabbou l-ʿarchi l-karim$q$, $q$Il n’y a de divinité digne d’adoration qu’Allah, le Très-Grand, le Longanime. Il n’y a de divinité digne d’adoration qu’Allah, Seigneur du Trône immense. Il n’y a de divinité digne d’adoration qu’Allah, Seigneur des cieux, Seigneur de la terre et Seigneur du noble Trône.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Détresse (karb) », invocation n° 1. Al-Bukhari 7/154 ; Muslim 4/2092.$q$, 1, 402, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$لاَ إِلَهَ إِلاَّ اللَّهُ الْعَظِيمُ الْحَلِيمُ، لاَ إِلَهَ إِلاَّ اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ، لاَ إِلَهَ إِلاَّ اللَّهُ رَبُّ السَّمَوَاتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيمِ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$اللَّهُمَّ رَحْمَتَكَ أَرْجُو، فَلاَ تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ، وَأَصْلِحْ لِي شَأْنِي كُلَّهُ، لاَ إِلَهَ إِلاَّ أَنْتَ$q$, $q$Allahoumma rahmataka ardjou, fala takilni ila nafsi tarfata ʿaynin, wa’aslih li cha’ni koullahou, la ilaha illa ant$q$, $q$Ô Allah, c’est Ta miséricorde que j’espère : ne me laisse pas à moi-même, le temps d’un clin d’œil, et remets en ordre toute ma situation. Il n’y a de divinité digne d’adoration que Toi.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Détresse (karb) », invocation n° 2. Abu Dawud 4/324 ; Ahmad 5/42 ; jugé hassan par al-Albani (Sahih Abi Dawud 3/959).$q$, 1, 403, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$اللَّهُمَّ رَحْمَتَكَ أَرْجُو، فَلاَ تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ، وَأَصْلِحْ لِي شَأْنِي كُلَّهُ، لاَ إِلَهَ إِلاَّ أَنْتَ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$لاَ إِلَهَ إِلاَّ أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ$q$, $q$La ilaha illa anta soubhanaka inni kountou mina dh-dhalimin$q$, $q$Il n’y a de divinité digne d’adoration que Toi ; gloire à Toi, j’ai été du nombre des injustes. (invocation de Yunus dans le ventre du poisson)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Détresse (karb) », invocation n° 3. At-Tirmidhi 5/529 ; al-Hakim 1/505 (jugé authentique, avec l’accord d’adh-Dhahabi) ; voir Sahih at-Tirmidhi 3/168.$q$, 1, 404, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$لاَ إِلَهَ إِلاَّ أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$اللَّهُ اللَّهُ رَبِّي لاَ أُشْرِكُ بِهِ شَيْئاً$q$, $q$Allahou llahou rabbi la ouchrikou bihi chay’a$q$, $q$Allah, Allah est mon Seigneur, je ne Lui associe rien.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Détresse (karb) », invocation n° 4. Abu Dawud 2/87 ; voir Sahih Ibn Majah 2/335.$q$, 1, 405, false
