INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$اللَّهُمَّ إِنَّا نَجْعَلُكَ فِي نُحُورِهِمْ، وَنَعُوذُ بِكَ مِنْ شُرُورِهِمْ$q$, $q$Allahoumma inna nadjʿalouka fi nouhourihim, wanaʿoudhou bika min chourourihim$q$, $q$Ô Allah, nous Te plaçons face à eux et nous cherchons refuge auprès de Toi contre leurs maux.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Rencontre d’un ennemi ou d’un puissant », invocation n° 1. Abu Dawud 2/89 ; al-Hakim 2/142 (jugé authentique, avec l’accord d’adh-Dhahabi).$q$, 1, 406, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$اللَّهُمَّ إِنَّا نَجْعَلُكَ فِي نُحُورِهِمْ، وَنَعُوذُ بِكَ مِنْ شُرُورِهِمْ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$اللَّهُمَّ أَنْتَ عَضُدِي، وَأَنْتَ نَصِيرِي، بِكَ أَحُولُ وَبِكَ أَصُولُ، وَبِكَ أُقَاتِلُ$q$, $q$Allahoumma anta ʿadoudi, wa’anta nasiri, bika ahoulou wabika asoulou, wabika ouqatil$q$, $q$Ô Allah, Tu es mon soutien et mon secours : par Toi je me déplace, par Toi je m’élance, par Toi je combats.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Rencontre d’un ennemi ou d’un puissant », invocation n° 2. Abu Dawud 3/42 ; at-Tirmidhi 5/572 (voir Sahih at-Tirmidhi 3/183).$q$, 1, 407, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$اللَّهُمَّ أَنْتَ عَضُدِي، وَأَنْتَ نَصِيرِي، بِكَ أَحُولُ وَبِكَ أَصُولُ، وَبِكَ أُقَاتِلُ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ$q$, $q$Hasbouna llahou waniʿma l-wakil$q$, $q$Allah nous suffit, et quel excellent garant !$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Rencontre d’un ennemi ou d’un puissant », invocation n° 3. Al-Bukhari 5/172.$q$, 1, 408, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$اللَّهُمَّ رَبَّ السَّمَوَاتِ السَّبْعِ، وَرَبَّ الْعَرْشِ الْعَظِيمِ، كُنْ لِي جَاراً مِنْ فُلاَنِ بْنِ فُلاَنٍ، وَأَحْزَابِهِ مِنْ خَلاَئِقِكَ، أَنْ يَفْرُطَ عَلَيَّ أَحَدٌ مِنْهُمْ أَوْ يَطْغَى، عَزَّ جَارُكَ، وَجَلَّ ثَنَاؤُكَ، وَلاَ إِلَهَ إِلاَّ أَنْتَ$q$, $q$Allahoumma rabba s-samawati s-sabʿi, warabba l-ʿarchi l-ʿadhimi, koun li djaran min foulani bni foulanin, wa’ahzabihi min khala’iqika, an yafrouta ʿalayya ahadoun minhoum aw yatgha, ʿazza djarouka, wadjalla thana’ouka, wala ilaha illa ant$q$, $q$Ô Allah, Seigneur des sept cieux et du Trône immense, sois mon protecteur contre un tel, fils d’un tel (dire son nom), et contre ses partisans parmi Tes créatures, afin qu’aucun d’eux ne se montre excessif ou n’abuse envers moi. Puissant est Ton protégé, grande est Ta louange, et il n’y a de divinité digne d’adoration que Toi.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Crainte de l’injustice d’un gouverneur », invocation n° 1. Al-Bukhari, al-Adab al-mufrad n° 707 ; jugé sahih par al-Albani (Sahih al-Adab al-mufrad n° 545).$q$, 1, 409, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$اللَّهُمَّ رَبَّ السَّمَوَاتِ السَّبْعِ، وَرَبَّ الْعَرْشِ الْعَظِيمِ، كُنْ لِي جَاراً مِنْ فُلاَنِ بْنِ فُلاَنٍ، وَأَحْزَابِهِ مِنْ خَلاَئِقِكَ، أَنْ يَفْرُطَ عَلَيَّ أَحَدٌ مِنْهُمْ أَوْ يَطْغَى، عَزَّ جَارُكَ، وَجَلَّ ثَنَاؤُكَ، وَلاَ إِلَهَ إِلاَّ أَنْتَ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$اللَّهُ أَكْبَرُ، اللَّهُ أَعَزُّ مِنْ خَلْقِهِ جَمِيعاً، اللَّهُ أَعَزُّ مِمَّا أَخَافُ وَأَحْذَرُ، أَعُوذُ بِاللَّهِ الَّذِي لاَ إِلَهَ إِلاَّ هُوَ، الْمُمْسِكِ السَّمَوَاتِ السَّبْعِ أَنْ يَقَعْنَ عَلَى الْأَرْضِ إِلاَّ بِإِذْنِهِ، مِنْ شَرِّ عَبْدِكَ فُلاَنٍ، وَجُنُودِهِ وَأَتْبَاعِهِ وَأَشْيَاعِهِ، مِنْ الْجِنِّ وَالإِنْسِ، اللَّهُمَّ كُنْ لِي جَاراً مِنْ شَرِّهِمْ، جَلَّ ثَنَاؤُكَ وَعَزَّ جَارُكَ، وَتَبَارَكَ اسْمُكَ، وَلاَ إِلَهَ غَيْرُكَ$q$, $q$Allahou akbarou, Allahou aʿazzou min khalqihi djamiʿan, Allahou aʿazzou mimma akhafou wa’ahdharou, aʿoudhou billahi-lladhi la ilaha illa houwa, al-moumsiki s-samawati s-sabʿi an yaqaʿna ʿala l-ardi illa bi’idhnihi, min charri ʿabdika foulanin, wadjounoudihi wa’atbaʿihi wa’achyaʿihi, min al-djinni wal-insi, Allahoumma koun li djaran min charrihim, djalla thana’ouka waʿazza djarouka, watabaraka-smouka, wala ilaha ghayrouk$q$, $q$Allah est le plus grand ; Allah est plus puissant que toute Sa création ; Allah est plus puissant que ce que je crains et redoute. Je cherche refuge auprès d’Allah, il n’y a de divinité digne d’adoration que Lui, Celui qui retient les sept cieux de tomber sur la terre sans Sa permission, contre le mal de Ton serviteur un tel (dire son nom), de ses soldats, de ses suiveurs et de ses partisans, parmi les djinns et les hommes. Ô Allah, sois mon protecteur contre leur mal ; grande est Ta louange, puissant est Ton protégé, béni soit Ton nom, et il n’y a de divinité digne d’adoration en dehors de Toi. (trois fois)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Crainte de l’injustice d’un gouverneur », invocation n° 2. Al-Bukhari, al-Adab al-mufrad n° 708 ; jugé sahih par al-Albani.$q$, 1, 410, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$اللَّهُ أَكْبَرُ، اللَّهُ أَعَزُّ مِنْ خَلْقِهِ جَمِيعاً، اللَّهُ أَعَزُّ مِمَّا أَخَافُ وَأَحْذَرُ، أَعُوذُ بِاللَّهِ الَّذِي لاَ إِلَهَ إِلاَّ هُوَ، الْمُمْسِكِ السَّمَوَاتِ السَّبْعِ أَنْ يَقَعْنَ عَلَى الْأَرْضِ إِلاَّ بِإِذْنِهِ، مِنْ شَرِّ عَبْدِكَ فُلاَنٍ، وَجُنُودِهِ وَأَتْبَاعِهِ وَأَشْيَاعِهِ، مِنْ الْجِنِّ وَالإِنْسِ، اللَّهُمَّ كُنْ لِي جَاراً مِنْ شَرِّهِمْ، جَلَّ ثَنَاؤُكَ وَعَزَّ جَارُكَ، وَتَبَارَكَ اسْمُكَ، وَلاَ إِلَهَ غَيْرُكَ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$اللَّهُمَّ مُنْزِلَ الْكِتَابِ، سَرِيعَ الْحِسَابِ، اهْزِمِ الأَحْزَابَ، اللَّهُمَّ اهْزِمْهُمْ وَزَلْزِلْهُمْ$q$, $q$Allahoumma mounzila l-kitabi, sariʿa l-hisabi, ihzimi l-ahzaba, Allahoumma-hzimhoum wazalzilhoum$q$, $q$Ô Allah, Toi qui as révélé le Livre, prompt dans le compte, mets en déroute les coalisés ! Ô Allah, mets-les en déroute et fais-les trembler.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Invocation contre l’ennemi », invocation n° 1. Muslim 3/1362.$q$, 1, 411, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$اللَّهُمَّ مُنْزِلَ الْكِتَابِ، سَرِيعَ الْحِسَابِ، اهْزِمِ الأَحْزَابَ، اللَّهُمَّ اهْزِمْهُمْ وَزَلْزِلْهُمْ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$اللَّهُمَّ اكْفِنِيهِمْ بِمَا شِئْتَ$q$, $q$Allahoumma-kfinihim bima chi’t$q$, $q$Ô Allah, protège-moi d’eux comme Tu veux.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Quand on craint un groupe de gens », invocation n° 1. Muslim 4/2300.$q$, 1, 412, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$اللَّهُمَّ اكْفِنِيهِمْ بِمَا شِئْتَ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$آمَنْتُ بِاللَّهِ وَرُسُلِهِ$q$, $q$Amantou billahi warousoulih$q$, $q$J’ai cru en Allah et en Ses messagers. (en cas de doute dans la foi : chercher refuge auprès d’Allah, cesser d’y penser, et dire cette formule)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Doute dans la foi », invocation n° 1. Al-Bukhari (Fath al-Bari 6/336) ; Muslim 1/120.$q$, 1, 413, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$آمَنْتُ بِاللَّهِ وَرُسُلِهِ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$﴿هُوَ الْأَوَّلُ وَالْآخِرُ وَالظَّاهِرُ وَالْبَاطِنُ وَهُوَ بِكُلِّ شَيْءٍ عَلِيمٌ﴾$q$, $q$Houwa l-awwalou wal-’akhirou wadh-dhahirou wal-batinou wahouwa bikoulli chay’in ʿalim.$q$, $q$« Il est le Premier et le Dernier, l’Apparent et le Caché, et Il est Omniscient. » (Coran 57:3 ; à réciter en cas de doute dans la foi)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Doute dans la foi », invocation n° 2. Coran, sourate al-Hadid, verset 3 ; Abu Dawud 4/329 ; jugé hassan par al-Albani (Sahih Abi Dawud 3/962).$q$, 1, 414, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$﴿هُوَ الْأَوَّلُ وَالْآخِرُ وَالظَّاهِرُ وَالْبَاطِنُ وَهُوَ بِكُلِّ شَيْءٍ عَلِيمٌ﴾$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$اللَّهُمَّ اكْفِنِي بِحَلاَلِكَ عَنْ حَرَامِكَ، وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ$q$, $q$Allahoumma-kfini bihalalika ʿan haramika, wa’aghnini bifadlika ʿamman siwak$q$, $q$Ô Allah, rends-moi suffisant par ce que Tu as permis pour que je m’abstienne de ce que Tu as interdit, et enrichis-moi par Ta grâce pour que je n’aie besoin que de Toi. (pour rembourser une dette ; la seconde formule du chapitre est celle de « Tristesse et souci » n° 2)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Pour rembourser une dette », invocation n° 1. At-Tirmidhi 5/560 (voir Sahih at-Tirmidhi 3/180).$q$, 1, 415, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$اللَّهُمَّ اكْفِنِي بِحَلاَلِكَ عَنْ حَرَامِكَ، وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ$q$, $q$Aʿoudhou billahi mina ch-chaytani r-radjim$q$, $q$Je cherche refuge auprès d’Allah contre Satan le maudit. (puis cracher légèrement sur sa gauche, trois fois : consigne du hadith de ‘Uthman ibn Abi l-‘As)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Murmures de Satan pendant la prière », invocation n° 1. Muslim 4/1729, hadith de ‘Uthman ibn Abi l-‘As (qu’Allah l’agrée) : « Je l’ai fait et Allah l’a éloigné de moi ».$q$, 1, 416, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$اللَّهُمَّ لاَ سَهْلَ إِلاَّ مَا جَعَلْتَهُ سَهْلاً، وَأَنْتَ تَجْعَلُ الْحَزْنَ إِذَا شِئْتَ سَهْلاً$q$, $q$Allahoumma la sahla illa ma djaʿaltahou sahlan, wa’anta tadjʿalou l-hazna idha chi’ta sahla$q$, $q$Ô Allah, il n’y a de facile que ce que Tu as rendu facile, et Tu rends facile le terrain difficile quand Tu le veux.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Quand une chose est difficile », invocation n° 1. Ibn Hibban n° 2427 (Mawarid) ; Ibn as-Sunni n° 351 ; al-Hafiz : hadith sahih ; jugé sahih par ‘Abd al-Qadir al-Arna’ut (Takhrij al-adhkar p. 106).$q$, 1, 417, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$اللَّهُمَّ لاَ سَهْلَ إِلاَّ مَا جَعَلْتَهُ سَهْلاً، وَأَنْتَ تَجْعَلُ الْحَزْنَ إِذَا شِئْتَ سَهْلاً$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$قَدَرُ اللَّهِ وَمَا شَاءَ فَعَلَ$q$, $q$Qadarou llahi wama cha’a faʿal$q$, $q$C’est le décret d’Allah, et Il fait ce qu’Il veut. (quand survient ce qu’on n’aime pas, ou quand on est dépassé par les événements)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Quand arrive ce qu’on n’aime pas », invocation n° 1. Muslim 4/2052 (hadith : « Le croyant fort est meilleur… Et s’il t’arrive quelque chose, ne dis pas “si j’avais fait ceci…”, mais dis : C’est le décret d’Allah et ce qu’Il a voulu, Il l’a fait »). Voir aussi Takhrij al-adhkar d’al-Arna’ut p. 106.$q$, 1, 418, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$قَدَرُ اللَّهِ وَمَا شَاءَ فَعَلَ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$لاَ بَأْسَ طَهُورٌ إِنْ شَاءَ اللَّهُ$q$, $q$La ba’sa tahouroun in cha’a llah$q$, $q$Pas de mal, c’est une purification, s’il plaît à Allah. (à dire à un malade que l’on visite)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Visite d’un malade », invocation n° 1. Al-Bukhari, Fath al-Bari 10/118.$q$, 1, 419, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$لاَ بَأْسَ طَهُورٌ إِنْ شَاءَ اللَّهُ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$أَسْأَلُ اللَّهَ الْعَظِيمَ رَبَّ الْعَرْشِ الْعَظِيمِ أَنْ يَشْفِيَكَ$q$, $q$As’alou llaha l-ʿadhima rabba l-ʿarchi l-ʿadhimi an yachfiyak$q$, $q$Je demande à Allah le Très-Grand, Seigneur du Trône immense, de te guérir. (sept fois)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Visite d’un malade », invocation n° 2. At-Tirmidhi, Abu Dawud : « Pas un musulman ne visite un malade dont le terme n’est pas venu et ne dit cela sept fois sans être guéri » (voir Sahih at-Tirmidhi 2/210 ; Sahih al-Jami‘ 5/180).$q$, 1, 420, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$أَسْأَلُ اللَّهَ الْعَظِيمَ رَبَّ الْعَرْشِ الْعَظِيمِ أَنْ يَشْفِيَكَ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَأَلْحِقْنِي بِالرَّفِيقِ الْأَعْلَى$q$, $q$Allahoumma-ghfir li, warhamni, wa’alhiqni bir-rafiqi l-aʿla$q$, $q$Ô Allah, pardonne-moi, fais-moi miséricorde et fais-moi rejoindre le Compagnon suprême.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Malade qui n’espère plus vivre », invocation n° 1. Al-Bukhari 7/10 ; Muslim 4/1893.$q$, 1, 421, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَأَلْحِقْنِي بِالرَّفِيقِ الْأَعْلَى$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$لاَ إِلَهَ إِلاَّ اللَّهُ إِنَّ لِلْمَوْتِ سَكَرَاتٍ$q$, $q$La ilaha illa llahou inna lilmawti sakarat$q$, $q$Il n’y a de divinité digne d’adoration qu’Allah ; la mort a certes ses agonies. (paroles du Prophète, selon ‘A’isha, alors qu’il passait ses mains mouillées sur son visage)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Malade qui n’espère plus vivre », invocation n° 2. Al-Bukhari, Fath al-Bari 8/144.$q$, 1, 422, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$لاَ إِلَهَ إِلاَّ اللَّهُ إِنَّ لِلْمَوْتِ سَكَرَاتٍ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$لاَ إِلَهَ إِلاَّ اللَّهُ وَاللَّهُ أَكْبَرُ، لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ، لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لاَ إِلَهَ إِلاَّ اللَّهُ لَهُ المُلْكُ وَلَهُ الْحَمْدُ، لاَ إِلَهَ إِلاَّ اللَّهُ وَلاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ$q$, $q$La ilaha illa llahou wallahou akbarou, la ilaha illa llahou wahdahou, la ilaha illa llahou wahdahou la charika lahou, la ilaha illa llahou lahou l-moulkou walahou l-hamdou, la ilaha illa llahou wala hawla wala qouwwata illa billah$q$, $q$Il n’y a de divinité digne d’adoration qu’Allah, et Allah est le plus grand. Il n’y a de divinité digne d’adoration qu’Allah, Seul. Il n’y a de divinité digne d’adoration qu’Allah, Seul, sans associé. Il n’y a de divinité digne d’adoration qu’Allah : à Lui la royauté et à Lui la louange. Il n’y a de divinité digne d’adoration qu’Allah, et il n’y a de force ni de puissance qu’en Allah.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Malade qui n’espère plus vivre », invocation n° 3. At-Tirmidhi, Ibn Majah ; jugé sahih par al-Albani (Sahih at-Tirmidhi 3/152 ; Sahih Ibn Majah 2/317).$q$, 1, 423, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$لاَ إِلَهَ إِلاَّ اللَّهُ وَاللَّهُ أَكْبَرُ، لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ، لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لاَ إِلَهَ إِلاَّ اللَّهُ لَهُ المُلْكُ وَلَهُ الْحَمْدُ، لاَ إِلَهَ إِلاَّ اللَّهُ وَلاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$أَعُوذُ بِاللَّهِ وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ وَأُحَاذِرُ$q$, $q$Aʿoudhou billahi waqoudratihi min charri ma adjidou wa’ouhadhir$q$, $q$Je cherche refuge auprès d’Allah et de Sa puissance contre le mal de ce que je ressens et de ce que je redoute. (poser la main sur l’endroit douloureux, dire d’abord trois fois « Au nom d’Allah », puis cette formule sept fois)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Douleur dans le corps », invocation n° 1. Muslim 4/1728.$q$, 1, 424, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$أَعُوذُ بِاللَّهِ وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ وَأُحَاذِرُ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$لاَ إِلَهَ إِلاَّ اللَّهُ$q$, $q$La ilaha illa llah$q$, $q$Il n’y a de divinité digne d’adoration qu’Allah ! (exclamation quand on est effrayé ou saisi par un événement grave)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Quand on est effrayé », invocation n° 1. Al-Bukhari, Fath al-Bari 6/181 ; Muslim 4/2208.$q$, 1, 425, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$لاَ إِلَهَ إِلاَّ اللَّهُ$q$);
